<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Overtime approvals | <?= e(config('app.name')) ?></title><link rel="stylesheet" href="<?= e(app_url('/assets/css/app.css?v=20260721-flexible')) ?>"></head><body>
<?php require BASE_PATH . '/app/Views/partials/nav.php'; ?><main class="container"><div class="page-heading"><div><p class="eyebrow">Attendance review</p><h1>Overtime approvals</h1><p class="muted">Only approved overtime is included in reports.</p></div></div>
<?php if ($flash): ?><div class="alert <?= e($flash['type']) ?>"><?= e($flash['message']) ?></div><?php endif; ?>
<section class="panel table-panel"><div class="table-wrap"><table><thead><tr><th>Employee</th><th>Date</th><th>Active</th><th>Excess</th><th>Status</th><th>Decision</th></tr></thead><tbody>
<?php foreach($items as $item): ?><tr><td><strong><?= e($item['employee_name']) ?></strong><small><?= e($item['employee_number']) ?></small></td><td><?= e($item['work_date']) ?></td><td><?= e(format_minutes(intdiv((int)$item['active_seconds'],60))) ?></td><td><strong><?= e(format_minutes((int)$item['overtime_minutes'])) ?></strong></td><td><span class="status-pill status-<?= e($item['overtime_status']) ?>"><?= e(ucfirst($item['overtime_status'])) ?></span></td><td><?php if($item['overtime_status']==='pending'): ?><div class="overtime-decision"><form method="post" action="<?= e(app_url('/overtime-approvals/'.$item['id'])) ?>"><?= csrf_field() ?><input type="hidden" name="review_choice" value="yes"><input name="review_note" maxlength="500" placeholder="Optional approval note"><button type="submit">Approve</button></form><form method="post" action="<?= e(app_url('/overtime-approvals/'.$item['id'])) ?>"><?= csrf_field() ?><input type="hidden" name="review_choice" value="no"><button type="submit" class="button-quiet danger">Reject</button></form></div><?php else: ?><small><?= e($item['overtime_review_notes'] ?? 'Reviewed') ?></small><?php endif; ?></td></tr><?php endforeach; ?>
<?php if($items===[]): ?><tr><td class="empty" colspan="6">No overtime items.</td></tr><?php endif; ?></tbody></table></div></section></main></body></html>
